CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',disabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,parent_id INTEGER REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS articles(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,author_id INTEGER REFERENCES users(id) ON DELETE SET NULL,kind TEXT NOT NULL DEFAULT 'article',year TEXT DEFAULT '',map_x REAL,map_y REAL,info_json TEXT NOT NULL DEFAULT '{}',views INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tags(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS article_tags(article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE,tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,PRIMARY KEY(article_id,tag_id));
CREATE TABLE IF NOT EXISTS article_relations(from_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE,to_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE,label TEXT NOT NULL DEFAULT 'Связано с',PRIMARY KEY(from_id,to_id));
CREATE TABLE IF NOT EXISTS article_images(id INTEGER PRIMARY KEY AUTOINCREMENT,article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE,filename TEXT NOT NULL,mime TEXT NOT NULL,data BLOB NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS history(id INTEGER PRIMARY KEY AUTOINCREMENT,article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_articles_category ON articles(category_id);CREATE INDEX IF NOT EXISTS idx_article_tags_tag ON article_tags(tag_id);CREATE INDEX IF NOT EXISTS idx_history_article ON history(article_id);CREATE INDEX IF NOT EXISTS idx_images_article ON article_images(article_id);